macro_rules! deps {
    () => {
        MoveMask!();
        Vector!();
        Mask!();
    };
}

macro_rules! aarch64neon {
    () => {
        deps!();
        # [cfg (target_arch = "aarch64")] mod aarch64neon { use core :: arch :: aarch64 :: * ; use super :: { MoveMask , Vector } ; impl Vector for uint8x16_t { const BYTES : usize = 16 ; const ALIGN : usize = Self :: BYTES - 1 ; type Mask = NeonMoveMask ; # [inline (always)] unsafe fn splat (byte : u8) -> uint8x16_t { vdupq_n_u8 (byte) } # [inline (always)] unsafe fn load_aligned (data : * const u8) -> uint8x16_t { Self :: load_unaligned (data) } # [inline (always)] unsafe fn load_unaligned (data : * const u8) -> uint8x16_t { vld1q_u8 (data) } # [inline (always)] unsafe fn movemask (self) -> NeonMoveMask { let asu16s = vreinterpretq_u16_u8 (self) ; let mask = vshrn_n_u16 (asu16s , 4) ; let asu64 = vreinterpret_u64_u8 (mask) ; let scalar64 = vget_lane_u64 (asu64 , 0) ; NeonMoveMask (scalar64 & 0x8888888888888888) } # [inline (always)] unsafe fn cmpeq (self , vector2 : Self) -> uint8x16_t { vceqq_u8 (self , vector2) } # [inline (always)] unsafe fn and (self , vector2 : Self) -> uint8x16_t { vandq_u8 (self , vector2) } # [inline (always)] unsafe fn or (self , vector2 : Self) -> uint8x16_t { vorrq_u8 (self , vector2) } # [doc = " This is the only interesting implementation of this routine."] # [doc = " Basically, instead of doing the \"shift right narrow\" dance, we use"] # [doc = " adjacent folding max to determine whether there are any non-zero"] # [doc = " bytes in our mask. If there are, *then* we'll do the \"shift right"] # [doc = " narrow\" dance. In benchmarks, this does lead to slightly better"] # [doc = " throughput, but the win doesn't appear huge."] # [inline (always)] unsafe fn movemask_will_have_non_zero (self) -> bool { let low = vreinterpretq_u64_u8 (vpmaxq_u8 (self , self)) ; vgetq_lane_u64 (low , 0) != 0 } } # [doc = " Neon doesn't have a `movemask` that works like the one in x86-64, so we"] # [doc = " wind up using a different method[1]. The different method also produces"] # [doc = " a mask, but 4 bits are set in the neon case instead of a single bit set"] # [doc = " in the x86-64 case. We do an extra step to zero out 3 of the 4 bits,"] # [doc = " but we still wind up with at least 3 zeroes between each set bit. This"] # [doc = " generally means that we need to do some division by 4 before extracting"] # [doc = " offsets."] # [doc = ""] # [doc = " In fact, the existence of this type is the entire reason that we have"] # [doc = " the `MoveMask` trait in the first place. This basically lets us keep"] # [doc = " the different representations of masks without being forced to unify"] # [doc = " them into a single representation, which could result in extra and"] # [doc = " unnecessary work."] # [doc = ""] # [doc = " [1]: https://community.arm.com/arm-community-blogs/b/infrastructure-solutions-blog/posts/porting-x86-vector-bitmask-optimizations-to-arm-neon"] # [derive (Clone , Copy , Debug)] pub (crate) struct NeonMoveMask (u64) ; impl NeonMoveMask { # [doc = " Get the mask in a form suitable for computing offsets."] # [doc = ""] # [doc = " The mask is always already in host-endianness, so this is a no-op."] # [inline (always)] fn get_for_offset (self) -> u64 { self . 0 } } impl MoveMask for NeonMoveMask { # [inline (always)] fn all_zeros_except_least_significant (n : usize) -> NeonMoveMask { debug_assert ! (n < 16) ; NeonMoveMask (! (((1 << n) << 2) - 1)) } # [inline (always)] fn has_non_zero (self) -> bool { self . 0 != 0 } # [inline (always)] fn count_ones (self) -> usize { self . 0 . count_ones () as usize } # [inline (always)] fn and (self , other : NeonMoveMask) -> NeonMoveMask { NeonMoveMask (self . 0 & other . 0) } # [inline (always)] fn or (self , other : NeonMoveMask) -> NeonMoveMask { NeonMoveMask (self . 0 | other . 0) } # [inline (always)] fn clear_least_significant_bit (self) -> NeonMoveMask { NeonMoveMask (self . 0 & (self . 0 - 1)) } # [inline (always)] fn first_offset (self) -> usize { (self . get_for_offset () . trailing_zeros () >> 2) as usize } # [inline (always)] fn last_offset (self) -> usize { 16 - (self . get_for_offset () . leading_zeros () >> 2) as usize - 1 } } }
    };
}

aarch64neon!();